class TestServiceStatus:
    """ServiceStatus enum integrity tests."""

    def test_enum_members(self):
        """All expected enum members should exist."""
        expected = {
            "UNKNOWN",
            "HEALTHY",
            "DEGRADED",
            "UNHEALTHY",
            "RESTARTING",
            "STOPPED",
        }
        actual = {status.name for status in ServiceStatus}
        assert expected.issubset(actual)

    def test_enum_values_are_strings(self):
        """Enum values should be strings for serialization."""
        for status in ServiceStatus:
            assert isinstance(status.value, str)

    def test_enum_unique_values(self):
        """Enum values should be unique."""
        values = [status.value for status in ServiceStatus]
        assert len(values) == len(set(values))

    def test_status_transition_valid(self):
        """Valid status transitions should be allowed."""
        transitions = {
            ServiceStatus.UNKNOWN: {ServiceStatus.HEALTHY, ServiceStatus.UNHEALTHY},
            ServiceStatus.HEALTHY: {ServiceStatus.DEGRADED, ServiceStatus.UNHEALTHY},
            ServiceStatus.DEGRADED: {ServiceStatus.HEALTHY, ServiceStatus.UNHEALTHY},
            ServiceStatus.UNHEALTHY: {ServiceStatus.RESTARTING, ServiceStatus.STOPPED},
            ServiceStatus.RESTARTING: {ServiceStatus.HEALTHY, ServiceStatus.UNHEALTHY},
            ServiceStatus.STOPPED: {ServiceStatus.RESTARTING},
        }
        for current, allowed in transitions.items():
            for target in ServiceStatus:
                if target in allowed:
                    assert SelfHealingInfra._is_valid_transition(current, target)
                else:
                    assert not SelfHealingInfra._is_valid_transition(current, target)


