class TestRaceConditionSafety:
    """Concurrent restart request safety tests."""

    @pytest.mark.asyncio
    async def test_concurrent_restart_requests(self, infra_instance: SelfHealingInfra):
        """Concurrent restart requests should be serialized."""
        infra_instance.config.cooldown_period = 0  # Disable cooldown for this test

        with patch("asyncio.create_subprocess_exec", new=AsyncMock()) as mock_subprocess:
            mock_proc = AsyncMock()
            mock_proc.returncode = 0
            mock_subprocess.return_value = mock_proc

            # Fire 5 concurrent restart requests
            tasks = [infra_instance.restart_service() for _ in range(5)]
            results = await asyncio.gather(*tasks)

            # All should succeed
            assert all(results)
            # But subprocess should only be called once (serialized)
            assert mock_subprocess.call_count == 1

    @pytest.mark.asyncio
    async def test_restart_lock_prevents_duplicate(self, infra_instance: SelfHealingInfra):
        """Restart lock should prevent duplicate restarts."""
        infra_instance._restart_lock = asyncio.Lock()

        async def slow_restart():
            async with infra_instance._restart_lock:
                await asyncio.sleep(0.1)
                return True

        with patch.object(infra_instance, "restart_service", new=slow_restart):
            # First call acquires lock
            task1 = asyncio.create_task(infra_instance.restart_service())
            await asyncio.sleep(0.01)  # Let task1 acquire lock

            # Second call should wait
            task2 = asyncio.create_task(infra_instance.restart_service())
            await asyncio.sleep(0.01)

            # Both should complete
            results = await asyncio.gather(task1, task2)
            assert all(results)


