class TestEdgeCases:
    """Edge case scenarios."""

    def test_unicode_service_name(self):
        """Service names with unicode should be accepted."""
        config = ServiceConfig(
            name="服务网关",
            health_endpoint="http://localhost:8080/health",
            restart_command=["systemctl", "restart", "swarm-api"],
        )
        assert config.name == "服务网关"

    def test_very_long_service_name(self):
        """Very long service names should be accepted."""
        long_name = "x" * 1000
        config = ServiceConfig(
            name=long_name,
            health_endpoint="http://localhost:8080/health",
            restart_command=["systemctl", "restart", "swarm-api"],
        )
        assert config.name == long_name

    def test_health_endpoint_with_query_params(self):
        """Health endpoint with query parameters should be valid."""
        config = ServiceConfig(
            name="api",
            health_endpoint="http://localhost:8080/health?check=full&timeout=5",
            restart_command=["systemctl", "restart", "swarm-api"],
        )
        assert "?" in config.health_endpoint

    def test_health_endpoint_https(self):
        """HTTPS health endpoints should be supported."""
        config = ServiceConfig(
            name="api",
            health_endpoint="https://secure.example.com/health",
            restart_command=["systemctl", "restart", "swarm-api"],
        )
        assert config.health_endpoint.startswith("https://")

    @pytest.mark.asyncio
    async def test_restart_with_sudo_command(self, infra_instance: SelfHealingInfra):
        """Restart command with sudo should work."""
        infra_instance.config.restart_command = ["sudo", "systemctl", "restart", "swarm-api"]

        with patch("asyncio.create_subprocess_exec", new=AsyncMock()) as mock_subprocess:
            mock_proc = AsyncMock()
            mock_proc.returncode = 0
            mock_subprocess.return_value = mock_proc

            result = await infra_instance.restart_service()
            assert result is True
            mock_subprocess.assert_called_once_with(
                "sudo", "systemctl", "restart", "swarm-api"
            )

    @pytest.mark.asyncio
    async def test_restart_with_env_vars(self, infra_instance: SelfHealingInfra):
        """Restart command with environment variables should work."""
        infra_instance.config.restart_command = ["env", "VAR=value", "systemctl", "restart", "swarm-api"]

        with patch("asyncio.create_subprocess_exec", new=AsyncMock()) as mock_subprocess:
            mock_proc = AsyncMock()
            mock_proc.returncode = 0
            mock_subprocess.return_value = mock_proc

            result = await infra_instance.restart_service()
            assert result is True
            mock_subprocess.assert_called_once_with(
                "env", "VAR=value", "systemctl", "restart", "swarm-api"
            )


